<?php require 'config.php';$id=(int)($_GET['id']??0);$st=db()->prepare("SELECT t.*,d.TenDiaDiem FROM tours t LEFT JOIN diadiem d ON d.MaDiaDiem=t.MaDiaDiem WHERE t.MaTour=? AND t.TrangThai='dang_mo'");$st->execute([$id]);$t=$st->fetch();$ok='';$err='';if($t&&$_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$date=$_POST['date']??'';$n=(int)($_POST['people']??1);if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$phone||$date<date('Y-m-d')||$n<1||$n>10)$err='Vui lòng kiểm tra lại thông tin đặt tour.';else{try{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO khachhang(HoTen,Email,SoDienThoai) VALUES(?,?,?)");$s->execute([$name,$email,$phone]);$cid=$pdo->lastInsertId();$s=$pdo->prepare("INSERT INTO dattour(MaKhachHang,MaTour,NgayKhoiHanh,SoNguoi,GiaTaiThoiDiemDat,TongTien,TrangThai,GhiChu) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$cid,$id,$date,$n,$t['GiaTour'],$n*$t['GiaTour'],'cho_xac_nhan',trim($_POST['note']??'')]);$order=$pdo->lastInsertId();$pdo->commit();$ok="Gửi yêu cầu thành công! Mã đơn #$order. Nhân viên sẽ liên hệ xác nhận.";}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$err='Không lưu được đơn. Hãy kiểm tra cơ sở dữ liệu.';}}}$title=$t?$t['TenTour'].' — TourVela':'Tour chưa sẵn sàng';$active='tours';require 'includes/header.php';if(!$t):?><section class="section empty"><h2>Chưa tìm thấy tour này</h2><a class="btn dark" href="tours.php">Quay lại danh sách ↗</a></section><?php else:?>
<section class="detailhero" style="background-image:linear-gradient(90deg,#17211bd9,#17211b44),url('<?=e($t['AnhDaiDien'])?>')"><div class="eyebrow light">● <?=e($t['TenDiaDiem'])?></div><h1><?=e($t['TenTour'])?></h1><p>◷ <?=(int)$t['SoNgay']?> ngày <?=(int)$t['SoDem']?> đêm &nbsp; · &nbsp; ★ 4.9/5</p></section><section class="detail section"><div><div class="eyebrow">● VỀ HÀNH TRÌNH NÀY</div><h2>Một trải nghiệm <em>đáng nhớ.</em></h2><p><?=nl2br(e($t['MoTa']))?></p><h3>Lịch trình dự kiến</h3><p><?=nl2br(e($t['LichTrinh']))?></p><div class="notice">Đơn đặt tour ở trạng thái “Chờ xác nhận”. Nhân viên sẽ liên hệ xác nhận lịch trình và giá cuối cùng.</div></div><aside class="booking"><small>Giá từ / người</small><strong><?=money($t['GiaTour'])?></strong><hr><h3>Giữ chỗ cho hành trình</h3><?php if($ok):?><div class="success"><?=e($ok)?></div><?php endif;?><?php if($err):?><div class="notice"><?=$err?></div><?php endif;?><form method="post" class="form"><label>Họ và tên<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Số điện thoại<input name="phone" required></label><div class="twocol"><label>Ngày khởi hành<input type="date" name="date" min="<?=date('Y-m-d')?>" required></label><label>Số người<select name="people"><?php for($i=1;$i<=10;$i++):?><option><?=$i?></option><?php endfor;?></select></label></div><label>Ghi chú<textarea name="note" rows="3"></textarea></label><button class="btn orange full">Gửi yêu cầu đặt tour ↗</button></form></aside></section><?php endif;require 'includes/footer.php';?>
